var pd = path.pathData();

for (var idx = 0; idx < pd.length; idx++) {

// Move each point along its normal

pd[idx].point.x += pd[idx].normal.x * amount;

pd[idx].point.y += pd[idx].normal.y * amount;

}

path.setPathData(pd);

mesh.setPathAtIndex(p, path);

}

}

