const inConn = api.getInConnection(selAttrs[0][0], selAttrs[0][1]);

let animCurveId = inConn.split('.')[0];

// 0: Constant

// 1: Loop

// 2: Loop with Offset

// 4: Oscillate

// 5: Zero

api.set(animCurveId, {"postInfinity": 1, "preInfinity": 1});

console.info("'Loop Before' and 'Loop After' set to 'Looping'.");

}
